import { readFileSync } from "node:fs";
import { resolve } from "node:path";

import { hexToBytes } from "@noble/hashes/utils.js";
import { describe, expect, it } from "vite-plus/test";

import { decodeEvm } from "../src/evm/index.ts";
import type { SignRequest } from "../src/index.ts";

/**
 * vectors/chains/fiat24.json — generated by scripts/vectors/fiat24.ts with Sourcify ABIs and
 * cast as independent oracles; every expected class/blind reason/warning is hand-written in the
 * generator, never captured from this decoder.
 */
type VectorCase = {
  readonly name: string;
  readonly signer: string;
  readonly request: SignRequest & { readonly message?: { readonly $bytes: string } };
  readonly expect: {
    readonly summary: string;
    readonly verifiability: string;
    readonly blind?: string;
    readonly warnings: ReadonlyArray<string>;
  };
};

const vectors = JSON.parse(
  readFileSync(resolve(import.meta.dirname, "../../../vectors/chains/fiat24.json"), "utf8"),
) as { cases: ReadonlyArray<VectorCase> };

const request = (v: VectorCase): SignRequest =>
  v.request.message?.$bytes === undefined
    ? v.request
    : ({
        ...v.request,
        message: hexToBytes(v.request.message.$bytes.replace(/^0x/, "")),
      } as SignRequest);

describe("Fiat24 vectors", () => {
  it.each(vectors.cases)("$name", (v) => {
    const intent = decodeEvm(request(v), v.signer);
    expect(intent.summary).toBe(v.expect.summary);
    expect(intent.verifiability).toBe(v.expect.verifiability);
    expect(intent.blind).toBe(v.expect.blind);
    expect((intent.warnings ?? []).map((w) => w.kind)).toStrictEqual(v.expect.warnings);
  });
});
